PREFIX dcam: <http://purl.org/dc/dcam/>

SELECT ?udcInfo ?lccInfo
WHERE {
  dcterms:UDC dcterms:hasVersion ?udcVersion ;
             rdfs:isDefinedBy ?udcDefinition ;
             rdfs:seeAlso ?udcSeeAlso ;
             rdf:type dcam:VocabularyEncodingScheme .
  dcterms:LCC dcterms:hasVersion ?lccVersion ;
             rdfs:isDefinedBy ?lccDefinition ;
             rdfs:seeAlso ?lccSeeAlso ;
             rdf:type dcam:VocabularyEncodingScheme .
  BIND (CONCAT("UDC Version: ", STR(?udcVersion), " | UDC Definition: ", STR(?udcDefinition), " | UDC See Also: ", STR(?udcSeeAlso)) AS ?udcInfo)
  BIND (CONCAT("LCC Version: ", STR(?lccVersion), " | LCC Definition: ", STR(?lccDefinition), " | LCC See Also: ", STR(?lccSeeAlso)) AS ?lccInfo)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>

SELECT ?property ?relation
WHERE {
  {
    ?property rdfs:subPropertyOf dcterms:coverage .
    BIND("subPropertyOf" AS ?relation)
  }
  UNION
  {
    dcterms:coverage rdfs:subPropertyOf ?property .
    BIND("superPropertyOf" AS ?relation)
  }
  UNION
  {
    ?property rdfs:range dcterms:coverage .
    BIND("range" AS ?relation)
  }
  UNION
  {
    dcterms:coverage rdfs:domain ?property .
    BIND("domain" AS ?relation)
  }
}

